import java.util.Scanner;
public class EulerTheorem {static long gcd(long a,long b){while(b!=0){long r=a%b;a=b;b=r;}return Math.abs(a);}public static void main(String[] args){Scanner sc=new Scanner(System.in);System.out.print("Enter a: ");long a=sc.nextLong();System.out.print("Enter n: ");int n=sc.nextInt();if(n<=0){System.out.println("n must be positive.");return;}int phi=0;for(int i=1;i<n;i++)if(gcd(n,i)==1)phi++;if(gcd(a,n)==1)System.out.println(a+"^"+phi+" is congruent to 1 modulo "+n+" (Euler's theorem)");else System.out.println("Cannot apply Euler's theorem: gcd(a,n) != 1");}}
